// Extrae y valida datos del evento appointment.created de Kaja
const body = $input.first().json.body || $input.first().json;

// Estructura esperada del payload de Kaja appointment.created
const appointment = body.appointment || body;

const customerPhone = appointment.customer?.phone
  || appointment.client?.phone
  || body.customer_phone
  || '';

const customerName = appointment.customer?.first_name
  || appointment.client?.name
  || body.customer_name
  || 'Paciente';

const startTime = appointment.start_time
  || appointment.start
  || body.start_time
  || '';

const staffName = appointment.staff?.first_name
  ? `${appointment.staff.first_name} ${appointment.staff.last_name || ''}`.trim()
  : (appointment.staff?.name || 'tu especialista');

const appointmentId = appointment.id || body.id || `appt_${Date.now()}`;

if (!customerPhone || !startTime) {
  throw new Error(`Datos de cita incompletos: phone=${customerPhone}, start=${startTime}`);
}

// Parsear la fecha de la cita
const appointmentDate = new Date(startTime);
if (isNaN(appointmentDate.getTime())) {
  throw new Error(`Fecha inválida: ${startTime}`);
}

// Calcular timestamp para recordatorio (24h antes de la cita)
const reminderAt = new Date(appointmentDate.getTime() - 24 * 60 * 60 * 1000);
const now = new Date();

// Si el recordatorio ya pasó (cita en menos de 24h), enviar en 30 segundos
const waitUntil = reminderAt > now ? reminderAt : new Date(now.getTime() + 30000);
const waitSeconds = Math.max(0, Math.floor((waitUntil.getTime() - now.getTime()) / 1000));

// Formatear fecha y hora para el mensaje (zona horaria Ciudad de México)
const dateOptions = { timeZone: 'America/Mexico_City', weekday: 'long', day: 'numeric', month: 'long' };
const timeOptions = { timeZone: 'America/Mexico_City', hour: '2-digit', minute: '2-digit', hour12: true };
const formattedDate = appointmentDate.toLocaleDateString('es-MX', dateOptions);
const formattedTime = appointmentDate.toLocaleTimeString('es-MX', timeOptions);

return [{
  json: {
    appointmentId,
    customerPhone,
    customerName,
    staffName,
    startTime,
    formattedDate,
    formattedTime,
    reminderAt: waitUntil.toISOString(),
    waitSeconds,
    businessName: $env['KAJA_BUSINESS_NAME'] || 'tu clínica de audiología'
  }
}];
